let mut res: Vec<OutRow> = Vec::new();
if t.n > 0 {
    let b = t.b[0];
    let a = t.a[0];
    res.push(OutRow { b: b, x: a as i128 });
    proof {
        assert(t.n == 1);
        assert(row_hit(t, 0));
        assert(key_at(t, 0) == (b as int));
        assert(min_x_val(t, 0) == (a as int));
        assert(min_x(t, (b as int), (a as int)));
        assert(res@[0].b == b);
        assert(res@[0].x as int == a as int);
        assert(forall|i0: int| #![trigger row_hit(t, i0)] row_hit(t, i0) ==> i0 == 0);
    }
}
res
